// Normaliza a resposta: banco vazio tem de virar lista vazia, não erro.
// jsonb costuma chegar já desserializado, mas alguns drivers devolvem string.
const linha = items.length ? items[0].json : {};
let demandas = linha.demandas ?? [];

if (typeof demandas === 'string') {
  try { demandas = JSON.parse(demandas); } catch (e) { demandas = []; }
}
if (!Array.isArray(demandas)) demandas = [];

return [{
  json: {
    demandas,
    atualizadoEm: linha.atualizado_em ?? null,
    atualizadoPor: linha.atualizado_por ?? null,
    total: demandas.length
  }
}];
